<!doctype html>
<html lang="fa" dir="rtl" data-theme="light">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <meta name="robots" content="noindex,follow">
  <meta name="description" content="این مسیر در نقشهٔ فلوسی پیدا نشد؛ اما راه برگشت هنوز روشن است.">
  <meta name="theme-color" content="#fffaf6">
  <title>مسیر پیدا نشد | استودیو فلوسی</title>
  <link rel="icon" href="/favicon.svg" type="image/svg+xml">
  <script>
    try {
      const theme = localStorage.getItem('flowsee-theme') || 'light';
      document.documentElement.dataset.theme = theme;
      if (theme === 'dark') document.querySelector('meta[name="theme-color"]').content = '#090e13';
    } catch (_) { document.documentElement.dataset.theme = 'light'; }
  </script>
  <style>
    @font-face{font-family:IRANSansX;src:url('/assets/fonts/IRANSansX-Regular.ttf') format('truetype');font-weight:400;font-display:swap}
    @font-face{font-family:IRANSansX;src:url('/assets/fonts/IRANSansX-Medium.ttf') format('truetype');font-weight:700;font-display:swap}
    :root{color-scheme:light;--bg:#fffaf6;--surface:#fff;--ink:#191919;--muted:#77716d;--line:#eee4dc;--soft:#fff0e8;--accent:#fe5400;--shadow:0 24px 80px #59230012}
    :root[data-theme="dark"]{color-scheme:dark;--bg:#090e13;--surface:#101820;--ink:#f2f5f7;--muted:#a1adb7;--line:#26323c;--soft:#251a15;--accent:#ff6a24;--shadow:0 24px 80px #0005}
    *{box-sizing:border-box}html{min-height:100%;background:var(--bg)}body{min-height:100vh;margin:0;background:radial-gradient(ellipse at 12% 10%,color-mix(in srgb,var(--accent) 8%,transparent),transparent 30%),radial-gradient(ellipse at 91% 85%,color-mix(in srgb,#ffc978 12%,transparent),transparent 28%),var(--bg);color:var(--ink);font-family:IRANSansX,Arial,sans-serif;transition:background .25s,color .25s}
    a{color:inherit;text-decoration:none}button{font:inherit}.shell{width:min(1160px,calc(100% - 48px));margin:auto}.topbar{height:84px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line)}.brand{display:inline-flex;align-items:center;gap:12px;font-weight:700;font-size:17px}.brand img{width:40px;height:36px;object-fit:contain}.top-actions{display:flex;align-items:center;gap:12px}.theme-toggle{display:grid;place-items:center;width:44px;height:44px;border:1px solid var(--line);border-radius:50%;background:var(--surface);color:var(--ink);cursor:pointer}.theme-toggle svg{width:19px;height:19px}.tiny-label{color:var(--muted);font-size:13px}
    main{min-height:calc(100vh - 85px);display:grid;align-items:center;padding:58px 0 70px}.layout{display:grid;grid-template-columns:minmax(0,1.02fr) minmax(360px,.98fr);align-items:center;gap:clamp(32px,7vw,90px)}.copy{position:relative;z-index:1}.eyebrow{display:inline-flex;align-items:center;gap:9px;padding:8px 13px;border:1px solid color-mix(in srgb,var(--accent) 24%,var(--line));border-radius:99px;background:var(--soft);color:var(--accent);font-size:13px;font-weight:700}.eyebrow i{width:7px;height:7px;border-radius:50%;background:var(--accent);box-shadow:0 0 0 5px color-mix(in srgb,var(--accent) 12%,transparent)}h1{max-width:620px;margin:22px 0 12px;font-size:clamp(36px,5vw,66px);line-height:1.28;letter-spacing:-.045em}h1 em{color:var(--accent);font-style:normal}.intro{max-width:510px;margin:0;color:var(--muted);font-size:17px;line-height:2.05}.actions{display:flex;flex-wrap:wrap;align-items:center;gap:12px;margin-top:30px}.button{min-height:52px;display:inline-flex;align-items:center;justify-content:center;gap:10px;padding:12px 20px;border:1px solid var(--line);border-radius:14px;background:var(--surface);font-weight:700;transition:transform .18s,border-color .18s,box-shadow .18s}.button:hover{transform:translateY(-2px);border-color:color-mix(in srgb,var(--accent) 40%,var(--line));box-shadow:0 10px 28px color-mix(in srgb,var(--accent) 10%,transparent)}.button-primary{border-color:var(--accent);background:var(--accent);color:#fff;box-shadow:0 12px 28px color-mix(in srgb,var(--accent) 22%,transparent)}.button svg{width:18px;height:18px}.footnote{margin-top:20px;color:var(--muted);font-size:12px}
    .scene{position:relative;min-height:490px;display:grid;place-items:center;isolation:isolate}.scene::before{position:absolute;z-index:-2;inset:7% 5%;border:1px solid var(--line);border-radius:48% 52% 45% 55%/48% 44% 56% 52%;background:linear-gradient(145deg,var(--surface),color-mix(in srgb,var(--soft) 65%,var(--surface)));box-shadow:var(--shadow);content:"";transform:rotate(-7deg)}.orbit{position:absolute;width:90%;height:72%;border:1px dashed color-mix(in srgb,var(--accent) 40%,var(--line));border-radius:50%;transform:rotate(-19deg)}.orbit::before,.orbit::after{position:absolute;width:12px;height:12px;border-radius:50%;background:var(--accent);box-shadow:0 0 0 7px color-mix(in srgb,var(--accent) 13%,transparent);content:""}.orbit::before{top:12%;right:17%}.orbit::after{bottom:13%;left:12%;width:8px;height:8px;background:#5a9bf6;box-shadow:0 0 0 6px #5a9bf622}.portal{position:relative;width:min(350px,76%);aspect-ratio:1;display:grid;place-items:center;border-radius:50%;background:radial-gradient(circle at 50% 46%,color-mix(in srgb,var(--accent) 16%,var(--surface)) 0 25%,transparent 26%),conic-gradient(from 20deg,transparent 0 12%,color-mix(in srgb,var(--accent) 38%,transparent) 13%,transparent 18% 36%,color-mix(in srgb,#608deb 34%,transparent) 37%,transparent 42% 66%,color-mix(in srgb,var(--accent) 24%,transparent) 67%,transparent 73%);filter:drop-shadow(0 20px 35px color-mix(in srgb,var(--accent) 10%,transparent));animation:float 7s ease-in-out infinite}.portal::before{position:absolute;inset:14%;border:1px solid color-mix(in srgb,var(--accent) 30%,var(--line));border-radius:50%;background:var(--bg);box-shadow:inset 0 0 55px color-mix(in srgb,var(--accent) 10%,transparent),0 0 0 12px color-mix(in srgb,var(--surface) 70%,transparent)}.portal-core{position:relative;z-index:1;text-align:center;direction:ltr}.portal-number{display:block;color:var(--accent);font:800 clamp(74px,11vw,126px)/.9 IRANSansX,Arial,sans-serif;letter-spacing:-.09em;text-shadow:0 8px 0 color-mix(in srgb,var(--accent) 12%,transparent)}.portal-caption{display:block;margin-top:13px;color:var(--muted);font-size:12px;letter-spacing:.23em;text-transform:uppercase}.float-card{position:absolute;display:flex;align-items:center;gap:10px;padding:11px 14px;border:1px solid var(--line);border-radius:14px;background:color-mix(in srgb,var(--surface) 88%,transparent);box-shadow:0 12px 32px #17191c12;backdrop-filter:blur(12px);font-size:12px}.float-card svg{width:18px;height:18px;color:var(--accent)}.float-card.one{top:17%;left:2%;animation:float 5s .3s ease-in-out infinite}.float-card.two{right:0;bottom:17%;animation:float 6s .8s ease-in-out infinite}.spark{position:absolute;color:var(--accent);font-size:24px}.spark-a{top:12%;right:19%}.spark-b{bottom:12%;left:17%;color:#5a9bf6}.route{position:absolute;right:50%;bottom:7%;width:80px;height:80px;border-right:1px solid color-mix(in srgb,var(--accent) 42%,transparent);border-bottom:1px solid color-mix(in srgb,var(--accent) 42%,transparent);border-radius:0 0 50px 0;transform:translateX(50%) rotate(-20deg);opacity:.6}
    @keyframes float{0%,100%{translate:0 0}50%{translate:0 -9px}}@media(max-width:800px){.shell{width:min(100% - 32px,560px)}.topbar{height:70px}.tiny-label{display:none}main{min-height:calc(100vh - 70px);padding:34px 0 48px}.layout{grid-template-columns:1fr;gap:14px}.copy{text-align:center}.eyebrow{font-size:12px}h1{margin:18px auto 10px;font-size:clamp(34px,9vw,50px)}.intro{margin:auto;font-size:15px}.actions{justify-content:center;margin-top:22px}.button{flex:1 1 190px}.footnote{margin-top:14px}.scene{min-height:min(82vw,400px);grid-row:1}.portal{width:min(270px,68vw)}.float-card.one{left:0;top:13%}.float-card.two{right:0;bottom:10%}.orbit{width:94%;height:68%}}
    @media(max-width:420px){.shell{width:calc(100% - 24px)}.topbar{height:64px}.brand{font-size:15px}.brand img{width:34px}.theme-toggle{width:40px;height:40px}.scene{min-height:290px}.portal{width:220px}.float-card{padding:9px 11px;font-size:11px}.actions{display:grid;grid-template-columns:1fr}.button{width:100%}.intro{font-size:14px}}
    @media(prefers-reduced-motion:reduce){*,*::before,*::after{scroll-behavior:auto!important;animation-duration:.01ms!important;animation-iteration-count:1!important;transition-duration:.01ms!important}}
  </style>
</head>
<body>
  <header class="topbar shell">
    <a class="brand" href="/" aria-label="استودیو فلوسی، صفحهٔ اصلی"><img src="/favicon.svg" width="40" height="36" alt=""><span>استودیو فلوسی</span></a>
    <div class="top-actions"><span class="tiny-label">گاهی بهترین مسیر، یک شروع تازه است.</span><button class="theme-toggle" id="theme-toggle" type="button" aria-label="تغییر پوسته" title="تغییر پوسته"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M20.4 15.2A8.6 8.6 0 0 1 8.8 3.6 8.6 8.6 0 1 0 20.4 15.2Z"/></svg></button></div>
  </header>
  <main class="shell">
    <div class="layout">
      <section class="copy" aria-labelledby="error-title">
        <span class="eyebrow"><i aria-hidden="true"></i> مختصات صفحه گم شده</span>
        <h1 id="error-title">این مسیر به <em>هیچ‌جا</em> نمی‌رسد.</h1>
        <p class="intro">صفحه‌ای که دنبالش بودی از نقشهٔ فلوسی خارج شده؛ اما مسیر برگشت هنوز روشن است. از اینجا دوباره راهت را پیدا کن.</p>
        <nav class="actions" aria-label="راه‌های ادامه">
          <a class="button button-primary" href="/" data-od-id="404-home"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-6H9v6H4a1 1 0 0 1-1-1z"/></svg>برگشت به خانه</a>
          <a class="button" href="/#portfolio" data-od-id="404-portfolio">دیدن نمونه‌کارها <span aria-hidden="true">↗</span></a>
          <a class="button" href="/blog" data-od-id="404-blog">خواندن وبلاگ <span aria-hidden="true">↗</span></a>
        </nav>
        <p class="footnote">خطای ۴۰۴ · نشانی واردشده را یک بار دیگر بررسی کن.</p>
      </section>
      <div class="scene" aria-hidden="true">
        <div class="orbit"></div><span class="spark spark-a">✳</span><span class="spark spark-b">✦</span>
        <div class="portal"><div class="portal-core"><span class="portal-number">404</span><span class="portal-caption">route not found</span></div></div>
        <div class="float-card one"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><path d="M4 5.5A2.5 2.5 0 0 1 6.5 3h11A2.5 2.5 0 0 1 20 5.5v13a2.5 2.5 0 0 1-2.5 2.5h-11A2.5 2.5 0 0 1 4 18.5zM8 8h8M8 12h5"/><path d="m15.5 16 1.5 1.5 3-3"/></svg><span>صفحه در دسترس نیست</span></div>
        <div class="float-card two"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3a14 14 0 0 1 0 18M12 3a14 14 0 0 0 0 18"/></svg><span>در حال پیدا کردن مسیر…</span></div><div class="route"></div>
      </div>
    </div>
  </main>
  <script>
    const themeButton = document.getElementById('theme-toggle');
    themeButton.addEventListener('click', () => {
      const next = document.documentElement.dataset.theme === 'dark' ? 'light' : 'dark';
      document.documentElement.dataset.theme = next;
      try { localStorage.setItem('flowsee-theme', next); } catch (_) {}
      document.querySelector('meta[name="theme-color"]').content = next === 'dark' ? '#090e13' : '#fffaf6';
    });
  </script>
</body>
</html>
